//! The menus' and draw lists' data. The types are in `tables.rs`.

#![allow(clippy::unreadable_literal)]

use super::item_params::{EventStart, OptionSwitch, StageCounter, VolumeKind};
use super::player::Setting;
use super::starters::Seats;
use super::tables::{DrawList, ItemSprite, Menu, MenuItem, MenuLabel};

/// A function a menu item names (its keys' and its action's).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ItemFn {
    FlipCodriver,
    BeginPlayerName,
    FlipGearing,
    NextGearing,
    PreviousGearing,
    PreviousCar,
    NextCar,
    PreviousSlideshowCar,
    NextSlideshowCar,
    PreviousCarPage,
    NextCarPage,
    PreviousSlideshowPicture,
    NextSlideshowPicture,
    NextController,
    PreviousController,
    KeepPlayerKeys,
    /// Runs `player_actions::raise_strength`.
    RaiseStrength,
    /// Runs `player_actions::lower_strength`.
    LowerStrength,
    BeginGearRatioEdit,
    BeginTyreEdit,
    OpenSteeringBox,
    OpenBrakeBox,
    BeginRideHeightEdit,
    BeginSuspensionStiffnessEdit,
    ToggleRepairChoice,
    NextScoresPage,
    PreviousScoresPage,
    PreviousSavePage,
    NextSavegamePage,
    PreviousReplayRange,
    NextReplayRange,
    BeginSavegameName,
    LoadSavegame,
    LoadChampionshipTableLoop,
    SaveSetupLoop,
    BeginSetupName,
    LoadSetupSlot,
    NextSetupPage,
    BeginReplayName,
    FlipYesNo,
    PreviousStagePage,
    NextStagePage,
    PreviousScreenMode,
    NextScreenMode,
    PreviousTextureSetting,
    NextTextureSetting,
    NextAudioQuality,
    PreviousAudioQuality,
    ViewStageDetails,
    ApplyScreenMode,
    /// Turns the chosen controller's H shifter switch over (`axes_items::toggle_shifter`).
    ToggleControllerMode,
    /// The chosen controller's button pictures, one style back / on (`axes_items::step_icons`).
    PreviousButtonIcons,
    NextButtonIcons,
    ReplayItemC,
    ReplayItemB,
    ReplayItemA,
    ToggleCaptionChoice,
    ShowIntro,
    RaiseSensitivity,
    LowerSensitivity,
    NextColourA,
    PreviousColourA,
    NextColourB,
    PreviousColourB,
    /// A function that does nothing.
    Nothing,
    GoBack,
    LeaveWithCarry,
    NextStageLoop,
    StartRallyLoop,
    NetworkRallyLoop,
    ChampionshipNewSimulationLoop,
    AudioSetupLoop,
    OptionsLoop,
    PlayerDetailsLoop,
    Player1DetailsLoop,
    Player2DetailsLoop,
    Player3DetailsLoop,
    Player4DetailsLoop,
    Player1ControllerLoop,
    Player1ButtonsLoop,
    Player2ControllerLoop,
    Player2ButtonsLoop,
    Player3ControllerLoop,
    Player3ButtonsLoop,
    Player4ControllerLoop,
    Player4ButtonsLoop,
    RedefineKeysPlayer1Loop,
    RedefineKeysPlayer2Loop,
    RedefineKeysPlayer3Loop,
    RedefineKeysPlayer4Loop,
    VisualPreferencesLoop,
    CarSpecificationLoop,
    SlideshowLoop,
    PreviousChoiceCar,
    NextChoiceCar,
    InGameOptionsLoop,
    AskToLeave,
    LoadChampionshipLoop,
    SaveChampionshipLoop,
    VisualOptionsLoop,
    AdvancedAudioLoop,
    SimpleSelectPlayersLoop,
    SwitchStageGroup,
    NextStageSub,
    PreviousStageSub,
    NextStageNumber,
    PreviousStageNumber,
    ArcadeSelectLevelLoop,
    StartArcade,
    TimeTrialSelectPlayersLoop,
    InformationLoop,
    ViewBestTimesLoop,
    ViewCoursesLoop,
    ViewBestScoresLoop,
    PreviousStageRows,
    NextStageRows,
    PreviousStageRowsOf90,
    NextStageRowsOf90,
    RallyResults,
    ChampionshipStandings,
    NewSimulationIfUnlocked,
    NewSimulationLoop,
    NetworkSettingsItem,
    JoinNetworkGame,
    HostNetworkGame,
    /// The current player's setting one step on (`up`) or back: nationality, view, second view, race number.
    StepSetting {
        setting: Setting,
        up: bool,
    },
    /// The current player's visual preference flipped (the visual preferences page's switches).
    Toggle(Setting),
    /// A volume one step up or down (the sound pages).
    Volume {
        which: VolumeKind,
        up: bool,
    },
    /// A switch of the options pages (sound names, stage records, visual and audio options).
    OptionSwitch(OptionSwitch),
    /// The stage pages' group or stage shown, one on or back.
    StageCounter {
        which: StageCounter,
        up: bool,
    },
    /// The controls page's key chosen to be redefined (the number is its row).
    ChooseKey(u8),
    /// The buttons page's row `n` (0 ..= 7 on the page shown) learnt.
    LearnRow(u8),
    /// The controller page's item that opens the axes page.
    AxesLoop,
    /// The buttons page's item that turns to the other page of controls.
    TurnControlsPage,
    /// The axes list's wheel switch (item 8) or full rotation (item 9) one step.
    AxisStep {
        up: bool,
    },
    /// The axes list's axis `n` (0 ..= 5) opens its page.
    AxisOpen(u8),
    /// The axis page's highlighted row one step: the axis, or one of its settings.
    AxisPageStep {
        up: bool,
    },
    /// The car specification of player 0 .. 3.
    PlayerCarSpecs(u8),
    /// The arcade level 1 .. 5 chosen.
    ArcadeLevel(u8),
    /// An event started for the seats (one player, split screen, two to four in turn).
    StartEvent(EventStart, Seats),
}

